// Economy and levels -------------------------------------------------------
// One query, three orderings. The existing leaderboards in users.sql back live
// slash commands and hardcode LIMIT 10, so they are left alone.
// The trailing `id` is a deterministic tiebreak; without it members tied on 0
// shuffle position between renders.
func (q *Queries) DashTopMembers(ctx context.Context, arg DashTopMembersParams) ([]DashTopMembersRow, error) {
	rows, err := q.db.Query(ctx, dashTopMembers, arg.GuildID, arg.Limit, arg.Sort)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DashTopMembersRow
	for rows.Next() {
		var i DashTopMembersRow
		if err := rows.Scan(
			&i.ID,
			&i.MessagesSent,
			&i.TotalXp,
			&i.StmpdCoins,
			&i.InHand,
			&i.NetWorth,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const dashTopModerators = `-- name: DashTopModerators :many
SELECT
    moderator_id,
    COUNT(*)::bigint AS actions,
    COUNT(*) FILTER (WHERE log_type IN ('ban', 'tempban', 'softban'))::bigint AS bans,
    COUNT(*) FILTER (WHERE log_type IN ('mute', 'tempmute'))::bigint          AS mutes,
    COUNT(*) FILTER (WHERE log_type = 'kick')::bigint                         AS kicks,
    MAX("time")::timestamp AS last_action
FROM modlogs
WHERE guild_id = $1
  AND "time" >= (now() AT TIME ZONE 'UTC') - make_interval(days => $3::int)
GROUP BY moderator_id
ORDER BY actions DESC, moderator_id
LIMIT $2
`

