const dashXPDistribution = `-- name: DashXPDistribution :many
SELECT
    width_bucket(
        u.total_xp, 0,
        GREATEST((SELECT MAX(mx.total_xp) FROM users mx WHERE mx.guild_id = $1), 1),
        20
    ) AS bucket,
    MIN(u.total_xp)::int AS min_xp,
    MAX(u.total_xp)::int AS max_xp,
    COUNT(*)::bigint     AS members
FROM users u
WHERE u.guild_id = $1 AND u.total_xp > 0
GROUP BY bucket
ORDER BY bucket
`

type DashXPDistributionRow struct {
	Bucket  int32 `json:"bucket"`
	MinXp   int32 `json:"minXp"`
	MaxXp   int32 `json:"maxXp"`
	Members int64 `json:"members"`
}

func (q *Queries) DashXPDistribution(ctx context.Context, guildID int64) ([]DashXPDistributionRow, error) {
	rows, err := q.db.Query(ctx, dashXPDistribution, guildID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DashXPDistributionRow
	for rows.Next() {
		var i DashXPDistributionRow
		if err := rows.Scan(
			&i.Bucket,
			&i.MinXp,
			&i.MaxXp,
			&i.Members,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
